// PAR-KS-01 — Consumer Support Manifest (baseline).
// Derives the consumer support surface from EXECUTABLE runtime behavior, never from
// documentation assertions. The manifest states the exact projection / semantic /
// analysis / result / return-channel versions the runtime actually dispatches, keeps
// PARTIAL / UNSUPPORTED / UNKNOWN first-class with profile-specific reason codes, and
// binds the consumer head/config so it is deterministic on the same head.
//
// The manifest is generated by running the real runtime modules that back the external
// v2 service (capability attestation, consumer profile, and intent dispatch readback).
// No server is started and no network/service is used: the derivation is the same code
// the service's /v2/capabilities, /v2/capability-manifest, and /v2/intents routes run.
// The manifest never carries a digest of itself.

import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  SBA_CONSUMER_PROFILE_SCHEMA,
  SBA_EXTERNAL_CONTRACT_ID,
  SBA_EXTERNAL_CONTRACT_VERSION,
  SBA_EXTERNAL_CAPABILITIES,
  SBA_PRODUCT_ID,
  SBA_PRODUCT_VERSION,
  capabilityAttestationV2,
  executeExternalIntentV2,
  externalBiConsumerProfileV1,
  sha256Digest,
  validateExternalIntentV2,
} from '../services/bi-agent/src/external-api-v2.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const MANIFEST_PATH = path.join(ROOT, 'contracts/analytics/consumer-support-manifest-v1.json');

export const CONSUMER_SUPPORT_MANIFEST_SCHEMA = 'kaleidosphere.analytics/consumer-support-manifest/v1';
export const CONSUMER_SUPPORT_MANIFEST_VERSION = '1.0.0';
export const CONSUMER_SUPPORT_ISSUE = 'PAR-KS-01';
export const CONSUMER_SUPPORT_NODE = 'PAR-KS-01';

// Profile-specific reason vocabulary. Reason codes are the first-class identity of a
// PARTIAL / UNSUPPORTED / UNKNOWN fact; a fact is never collapsed to supported:false,
// emptied, or omitted.
export const REASON = Object.freeze({
  PARTIAL_EXTERNAL_INTENT_NOT_DISPATCHABLE: 'EXTERNAL_INTENT_NOT_DISPATCHABLE',
  UNSUPPORTED_SOURCE_DATABASE_CREDENTIALS: 'UNSUPPORTED_SOURCE_DATABASE_CREDENTIALS',
  UNSUPPORTED_FREE_SQL: 'UNSUPPORTED_FREE_SQL',
  UNSUPPORTED_RAW_SOURCE_ROWS: 'UNSUPPORTED_RAW_SOURCE_ROWS',
  UNSUPPORTED_MODEL_MUTATION: 'UNSUPPORTED_MODEL_MUTATION',
  UNSUPPORTED_DIRECT_SUPERSET_MUTATION_INTENT: 'UNSUPPORTED_DIRECT_SUPERSET_MUTATION_INTENT',
  UNKNOWN_NO_RESIDUAL_AT_HEAD: 'NO_RESIDUAL_UNKNOWN_AT_HEAD',
});

export const REASON_FOR_SURFACE = Object.freeze({
  sourceDatabaseCredentials: REASON.UNSUPPORTED_SOURCE_DATABASE_CREDENTIALS,
  freeSql: REASON.UNSUPPORTED_FREE_SQL,
  rawSourceRows: REASON.UNSUPPORTED_RAW_SOURCE_ROWS,
  modelMutation: REASON.UNSUPPORTED_MODEL_MUTATION,
  directSupersetMutationIntent: REASON.UNSUPPORTED_DIRECT_SUPERSET_MUTATION_INTENT,
});

// Task-required nonclaims: no producer-truth, no broad analytics support, no manually
// asserted runtime capability.
export const CONSUMER_SUPPORT_NONCLAIMS = Object.freeze([
  'No producer-truth claim: this manifest states only the consumer support surface derived from executable runtime behavior; it asserts nothing about any upstream producer, source system, or external release truth.',
  'No broad analytics support: the manifest is scoped to the one external consumer profile (superset-bi-agent.external v2); it does not claim support for any analytics domain, projection profile, or capability beyond the runtime-derived set.',
  'No manually asserted runtime capability: every supported/partial/unsupported fact, every reason code, and every channel version is derived from the live runtime (capability attestation, consumer profile, and intent dispatch); no capability is asserted by documentation, hand-edit, or caller input.',
]);

const CHANNEL_KEYS = Object.freeze(['analysis', 'projection', 'result', 'returnChannel', 'semantic']);
const STATUS_SUPPORTED = 'SUPPORTED';
const STATUS_PARTIAL = 'PARTIAL';
const STATUS_UNSUPPORTED = 'UNSUPPORTED';
const STATUS_UNKNOWN = 'UNKNOWN';

const sha256hex = (value) => createHash('sha256').update(value).digest('hex');

export function fail(code) {
  const error = new Error(code);
  error.code = code;
  throw error;
}

// Normalized KaleidoSphere head. Bound into the manifest so a stale/substituted runtime
// (different commit or tree) is denied by the verifier.
export function gitHeads() {
  const resolve = (ref) => {
    const result = spawnSync('git', ['rev-parse', ref], { cwd: ROOT, encoding: 'utf8' });
    if (result.status !== 0) fail('CONSUMER_SUPPORT_MANIFEST_HEAD_UNRESOLVED');
    return result.stdout.trim();
  };
  return { commitOid: resolve('HEAD'), treeOid: resolve('HEAD^{tree}') };
}

// Machine-independent runtime config identity: the canonicalizer bytes, the bi-agent
// package bytes, and the product/contract versions. Deterministic per head and stable
// across machines, so the manifest is deterministic on the same head.
export function buildConfigIdentity() {
  const canonicalJsonSha256 = sha256hex(readFileSync(path.join(ROOT, 'services/bi-control/src/canonical-json.js')));
  const packageSha256 = sha256hex(readFileSync(path.join(ROOT, 'services/bi-agent/package.json')));
  const config = {
    canonicalJsonSha256,
    contractVersion: SBA_EXTERNAL_CONTRACT_VERSION,
    packageSha256,
    productVersion: SBA_PRODUCT_VERSION,
  };
  return { config, configSha256: sha256hex(canonicalJsonObject(config)) };
}

// Minimal canonical JSON (sorted keys, no whitespace) for config-identity hashing.
// Kept local so the config identity does not depend on the external-api module's
// canonicalizer beyond the attestation/profile/integrity digests.
function canonicalJsonObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    if (typeof value === 'string') return JSON.stringify(value);
    if (typeof value === 'boolean' || typeof value === 'number') return String(value);
    return 'null';
  }
  const parts = Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJsonObject(value[key])}`);
  return `{${parts.join(',')}}`;
}

// Stub handlers that fully populate the runtime's public readback mappers so the
// envelope/readback schema versions are observed from real dispatch, not read by hand.
const HEX64 = '0'.repeat(64);
const STUB_STATUS = { providerMode: 'consumer-manifest-derivation', status: 'ok' };
const STUB_ANALYZE = {
  receiptId: 'consumer-manifest-receipt',
  status: 'COMPLETED',
  sourceMode: 'read-only',
  engine: 'oracle',
  scope: { schemas: [] },
  safety: { source_read_only: 1, queryPackSelectOnly: true },
  analysis: { runtimeValidation: 'ok', snapshotSha256: HEX64 },
  projection: { sha256: HEX64 },
};
const STUB_READBACK = {
  receiptId: 'consumer-manifest-receipt',
  summary: { source_engine: 'oracle', source_mode: 'read-only', status: 'COMPLETED', snapshot_sha256: HEX64, source_read_only: 1 },
  catalogSnapshot: { schemas: [] },
  technicalOverview: 'none',
  publication: { status: 'NOT_APPLIED' },
};

// Executes the live runtime and observes the exact channel versions it dispatches.
// projection: the intent-request schema the gate accepts (v2 accepted / v1 denied).
// semantic:   the consumer-profile schema the runtime emits.
// analysis:   the analysis-readback schema observed from a real analyze dispatch.
// result:     the intent-result envelope schema observed from a real status dispatch.
// returnChannel: the superset-readback schema observed from a real readback dispatch.
export async function deriveChannelVersions() {
  const accepted = validateExternalIntentV2({
    schemaVersion: 'superset-bi-agent.external/intent-request/v2',
    requestId: 'consumer-manifest-probe',
    action: 'status',
  });
  let v1Denied;
  try {
    validateExternalIntentV2({ schemaVersion: 'superset-bi-agent.external/intent-request/v1', requestId: 'consumer-manifest-probe', action: 'status' });
    v1Denied = null;
  } catch (error) {
    v1Denied = error.code;
  }
  const profile = externalBiConsumerProfileV1();
  const statusEnvelope = await executeExternalIntentV2(
    { schemaVersion: 'superset-bi-agent.external/intent-request/v2', requestId: 'consumer-manifest-status', action: 'status' },
    { status: async () => STUB_STATUS },
  );
  const analyzeEnvelope = await executeExternalIntentV2(
    { schemaVersion: 'superset-bi-agent.external/intent-request/v2', requestId: 'consumer-manifest-analyze', action: 'analyze' },
    { analyze: async () => STUB_ANALYZE },
  );
  const readbackEnvelope = await executeExternalIntentV2(
    { schemaVersion: 'superset-bi-agent.external/intent-request/v2', requestId: 'consumer-manifest-readback', action: 'readback' },
    { readback: async () => STUB_READBACK },
  );
  return {
    projection: {
      status: STATUS_SUPPORTED,
      version: accepted.schemaVersion,
      reasonCode: null,
      evidence: { derivedFrom: 'validateExternalIntentV2', readback: 'acceptedRequest.schemaVersion', negativeProbe: `v1 denied ${v1Denied}` },
    },
    semantic: {
      status: STATUS_SUPPORTED,
      version: profile.schemaVersion,
      reasonCode: null,
      evidence: { derivedFrom: 'externalBiConsumerProfileV1', readback: 'profile.schemaVersion' },
    },
    analysis: {
      status: STATUS_SUPPORTED,
      version: analyzeEnvelope.result.schemaVersion,
      reasonCode: null,
      evidence: { derivedFrom: 'executeExternalIntentV2[analyze]', readback: 'result.schemaVersion' },
    },
    result: {
      status: STATUS_SUPPORTED,
      version: statusEnvelope.schemaVersion,
      reasonCode: null,
      evidence: { derivedFrom: 'executeExternalIntentV2[status]', readback: 'envelope.schemaVersion' },
    },
    returnChannel: {
      status: STATUS_SUPPORTED,
      version: readbackEnvelope.result.schemaVersion,
      reasonCode: null,
      evidence: { derivedFrom: 'executeExternalIntentV2[readback]', readback: 'result.schemaVersion' },
    },
  };
}

// Derives the first-class support partition from the runtime-produced consumer profile.
// Every capability lands in exactly one of supported / partial; every boundary surface
// lands in unsupported; the residual unknown set is computed as the set difference.
export function deriveSupportPartition(profile) {
  const supported = profile.supported.map((item) => ({ ...item, status: STATUS_SUPPORTED, reasonCode: null }));
  const partial = profile.partial.map((item) => ({ ...item, status: STATUS_PARTIAL, reasonCode: REASON.PARTIAL_EXTERNAL_INTENT_NOT_DISPATCHABLE }));
  const unsupported = profile.unsupported.map((item) => ({ ...item, status: STATUS_UNSUPPORTED, reasonCode: REASON_FOR_SURFACE[item.surface] }));

  // Universe = every runtime capability (by id) and every boundary surface. Unknown is
  // the residual after the runtime asserts everything it knows; at this head it is empty.
  const capabilityIds = new Set(SBA_EXTERNAL_CAPABILITIES.map((capability) => capability.id));
  const assertedCapabilityIds = new Set([...profile.supported, ...profile.partial].map((item) => item.id));
  const unknownCapabilityIds = [...capabilityIds].filter((id) => !assertedCapabilityIds.has(id));
  const unknown = unknownCapabilityIds.map((id) => ({ id, status: STATUS_UNKNOWN, reasonCode: REASON.UNKNOWN_NO_RESIDUAL_AT_HEAD }));

  const unsupportedVocabulary = [...new Set(unsupported.map((item) => item.reasonCode))].sort();
  const reasonCodes = {
    partial: REASON.PARTIAL_EXTERNAL_INTENT_NOT_DISPATCHABLE,
    unknown: REASON.UNKNOWN_NO_RESIDUAL_AT_HEAD,
    unsupported: unsupportedVocabulary,
  };
  return {
    supported,
    partial,
    unsupported,
    unknown,
    reasonCodes,
  };
}

// The exact consumer identity + the runtime-derived content. This is the single source
// the builder assembles and the verifier recomputes, so a drift (stale/substituted
// runtime) is detected by comparing the manifest to this live truth.
export async function deriveRuntimeSupport() {
  const attestation = capabilityAttestationV2();
  const profile = externalBiConsumerProfileV1();
  const channels = await deriveChannelVersions();
  const support = deriveSupportPartition(profile);
  return {
    consumer: {
      product: { id: SBA_PRODUCT_ID, version: SBA_PRODUCT_VERSION, component: attestation.product.component },
      contract: { id: SBA_EXTERNAL_CONTRACT_ID, version: SBA_EXTERNAL_CONTRACT_VERSION },
      profileSchema: SBA_CONSUMER_PROFILE_SCHEMA,
      profileDigest: profile.attestation.digest,
    },
    capabilityAttestationDigest: attestation.attestation.digest,
    channels,
    support,
  };
}

export async function buildConsumerSupportManifest({ heads, config }) {
  const runtime = await deriveRuntimeSupport();
  const body = {
    schemaVersion: CONSUMER_SUPPORT_MANIFEST_SCHEMA,
    manifestVersion: CONSUMER_SUPPORT_MANIFEST_VERSION,
    issue: CONSUMER_SUPPORT_ISSUE,
    consumer: runtime.consumer,
    capabilityAttestationDigest: runtime.capabilityAttestationDigest,
    channels: runtime.channels,
    support: runtime.support,
    nonclaims: [...CONSUMER_SUPPORT_NONCLAIMS],
    bindings: {
      kaleidosphereHead: heads,
      config,
    },
  };
  // Integrity is a digest of the body only; the manifest never carries its own digest.
  return { ...body, integrity: { algorithm: 'sha256-canonical-json', digest: sha256Digest(body) } };
}

function deepEqual(left, right) {
  return sha256Digest(left) === sha256Digest(right);
}

// Verifies a manifest against live runtime truth. A stale or substituted runtime (wrong
// head, wrong config, substituted attestation/profile, drifted channel, or a support
// partition that collapsed PARTIAL/UNSUPPORTED/UNKNOWN) is denied with a specific code.
//
// options: { expectedHead: {commitOid,treeOid}, configSha256, strict }
export async function verifyConsumerSupportManifest(manifest, { expectedHead, configSha256, strict = true }) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) fail('CONSUMER_SUPPORT_MANIFEST_STATE_DENIED');

  const { integrity, ...body } = manifest;
  if (integrity?.algorithm !== 'sha256-canonical-json' || integrity?.digest !== sha256Digest(body)) fail('CONSUMER_SUPPORT_MANIFEST_INTEGRITY_DENIED');
  if (manifest.schemaVersion !== CONSUMER_SUPPORT_MANIFEST_SCHEMA
    || manifest.manifestVersion !== CONSUMER_SUPPORT_MANIFEST_VERSION
    || manifest.issue !== CONSUMER_SUPPORT_ISSUE) fail('CONSUMER_SUPPORT_MANIFEST_SCHEMA_DENIED');

  const runtime = await deriveRuntimeSupport();

  if (!deepEqual(manifest.consumer, runtime.consumer)) fail('CONSUMER_SUPPORT_MANIFEST_CONSUMER_DRIFT_DENIED');
  if (typeof manifest.capabilityAttestationDigest !== 'string'
    || manifest.capabilityAttestationDigest !== runtime.capabilityAttestationDigest) fail('CONSUMER_SUPPORT_MANIFEST_ATTESTATION_STALE_DENIED');
  for (const key of CHANNEL_KEYS) {
    const entry = manifest.channels?.[key];
    if (entry === null || typeof entry !== 'object' || entry.version !== runtime.channels[key].version) fail('CONSUMER_SUPPORT_MANIFEST_CHANNEL_DRIFT_DENIED');
  }

  verifySupportShape(manifest.support);
  if (!deepEqual(manifest.support, runtime.support)) fail('CONSUMER_SUPPORT_MANIFEST_SUPPORT_DRIFT_DENIED');

  if (deepEqual(manifest.nonclaims, CONSUMER_SUPPORT_NONCLAIMS) === false) fail('CONSUMER_SUPPORT_MANIFEST_NONCLAIM_DENIED');

  const head = manifest.bindings?.kaleidosphereHead;
  if (head === null || typeof head !== 'object'
    || head.commitOid !== expectedHead?.commitOid || head.treeOid !== expectedHead?.treeOid) fail('CONSUMER_SUPPORT_MANIFEST_HEAD_DENIED');
  if (strict) {
    const config = manifest.bindings?.config;
    if (config === null || typeof config !== 'object' || sha256hex(canonicalJsonObject(config)) !== configSha256) fail('CONSUMER_SUPPORT_MANIFEST_CONFIG_DENIED');
  }
  return { state: 'VERIFIED' };
}

// First-class negative-shape checks. A fact is denied if it is collapsed to
// supported:false, empties a required category, drops a key, or loses its reason code.
function verifySupportShape(support) {
  if (support === null || typeof support !== 'object' || Array.isArray(support)) fail('CONSUMER_SUPPORT_MANIFEST_SUPPORT_SHAPE_DENIED');
  for (const key of ['supported', 'partial', 'unsupported', 'unknown', 'reasonCodes']) {
    if (!(key in support)) fail('CONSUMER_SUPPORT_MANIFEST_SUPPORT_SHAPE_DENIED');
  }
  if (!Array.isArray(support.supported) || !Array.isArray(support.partial)
    || !Array.isArray(support.unsupported) || !Array.isArray(support.unknown)) fail('CONSUMER_SUPPORT_MANIFEST_SUPPORT_SHAPE_DENIED');

  for (const item of support.unsupported) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) fail('CONSUMER_SUPPORT_MANIFEST_UNSUPPORTED_SHAPE_DENIED');
    if (item.status !== STATUS_UNSUPPORTED) fail('CONSUMER_SUPPORT_MANIFEST_UNSUPPORTED_SHAPE_DENIED');
    if (typeof item.surface !== 'string' || item.surface.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_UNSUPPORTED_SHAPE_DENIED');
    if (typeof item.reasonCode !== 'string' || item.reasonCode.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_UNSUPPORTED_SHAPE_DENIED');
    if ('supported' in item) fail('CONSUMER_SUPPORT_MANIFEST_UNSUPPORTED_SHAPE_DENIED');
  }
  for (const item of support.partial) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) fail('CONSUMER_SUPPORT_MANIFEST_PARTIAL_SHAPE_DENIED');
    if (item.status !== STATUS_PARTIAL) fail('CONSUMER_SUPPORT_MANIFEST_PARTIAL_SHAPE_DENIED');
    if (typeof item.reasonCode !== 'string' || item.reasonCode.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_PARTIAL_SHAPE_DENIED');
    if ('supported' in item) fail('CONSUMER_SUPPORT_MANIFEST_PARTIAL_SHAPE_DENIED');
  }
  for (const item of support.unknown) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) fail('CONSUMER_SUPPORT_MANIFEST_UNKNOWN_SHAPE_DENIED');
    if (item.status !== STATUS_UNKNOWN) fail('CONSUMER_SUPPORT_MANIFEST_UNKNOWN_SHAPE_DENIED');
    if (typeof item.reasonCode !== 'string' || item.reasonCode.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_UNKNOWN_SHAPE_DENIED');
  }
  const vocabulary = support.reasonCodes?.unsupported;
  if (!Array.isArray(vocabulary) || vocabulary.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_REASON_CODE_DENIED');
  if (new Set(vocabulary).size !== vocabulary.length) fail('CONSUMER_SUPPORT_MANIFEST_REASON_CODE_DENIED');
  if (typeof support.reasonCodes?.partial !== 'string' || support.reasonCodes.partial.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_REASON_CODE_DENIED');
  if (typeof support.reasonCodes?.unknown !== 'string' || support.reasonCodes.unknown.length === 0) fail('CONSUMER_SUPPORT_MANIFEST_REASON_CODE_DENIED');
}

// CLI: by default, regenerate the committed baseline at the current head. With
// `--check`, run the build gate non-mutatingly: prove the committed baseline is
// byte-reproducible from the live runtime at the head the file records and verifies
// VERIFIED against the live runtime; any drift fails with a specific code. Runs only
// when invoked directly; importing this module has no side effects.
async function main(check = false) {
  if (check) {
    const baseline = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'));
    const recordedHead = baseline?.bindings?.kaleidosphereHead;
    if (recordedHead === null || typeof recordedHead !== 'object'
      || typeof recordedHead.commitOid !== 'string' || typeof recordedHead.treeOid !== 'string') fail('CONSUMER_SUPPORT_MANIFEST_CHECK_HEAD_UNRESOLVED');
    const { config, configSha256 } = buildConfigIdentity();
    const fresh = await buildConsumerSupportManifest({ heads: recordedHead, config });
    if (fresh.integrity.digest !== baseline?.integrity?.digest) fail('CONSUMER_SUPPORT_MANIFEST_CHECK_DRIFT_DENIED');
    await verifyConsumerSupportManifest(baseline, { expectedHead: recordedHead, configSha256, strict: true });
    console.log('consumer-support-manifest build gate: VERIFIED');
    console.log(`  head:      ${recordedHead.commitOid}`);
    console.log(`  integrity: ${baseline.integrity.digest}`);
    return;
  }
  const heads = gitHeads();
  const { config } = buildConfigIdentity();
  const manifest = await buildConsumerSupportManifest({ heads, config });
  mkdirSync(path.dirname(MANIFEST_PATH), { recursive: true });
  writeFileSync(MANIFEST_PATH, `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(`Wrote ${path.relative(ROOT, MANIFEST_PATH)}`);
  console.log(`  schema:    ${manifest.schemaVersion} v${manifest.manifestVersion}`);
  console.log(`  head:      ${heads.commitOid}`);
  console.log(`  channels:  ${CHANNEL_KEYS.map((key) => `${key}=${manifest.channels[key].version.split('/').pop()}`).join(' ')}`);
  console.log(`  support:   supported=${manifest.support.supported.length} partial=${manifest.support.partial.length} unsupported=${manifest.support.unsupported.length} unknown=${manifest.support.unknown.length}`);
  console.log(`  integrity: ${manifest.integrity.digest}`);
}

const isDirectRun = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isDirectRun) {
  main(process.argv.includes('--check')).catch((error) => {
    console.error(`CONSUMER_SUPPORT_MANIFEST_BUILD_DENIED ${error.code ?? error.message}`);
    process.exit(1);
  });
}